        var copy=image.Clone();copy.ImageZones[0].X=.01f;check(image.ImageZones[0].X!=copy.ImageZones[0].X,"Cloning images deep-copies zone geometry and settings");var project=Snapshot();using(var stream=new MemoryStream()){var xml=new System.Xml.Serialization.XmlSerializer(typeof(Project));xml.Serialize(stream,project);stream.Position=0;var saved=(Project)xml.Deserialize(stream);check(saved.Marks[0].ImageZones.Count==1&&saved.Marks[0].ImageZones[0].Settings.Exposure==1,"Editable projects retain zone shape, feather and adjustments");}
        using(var frame=new Bitmap(inspector.Parent.Width,inspector.Parent.Height)){inspector.Parent.DrawToBitmap(frame,new Rectangle(Point.Empty,frame.Size));frame.Save(Path.Combine(folder,"zone-adjustment-controls.png"));}
        CloseImageEffects();using(var source=Blank(200,160))LoadImageDocument(new Bitmap(source),"Background layout");var original=Marks[0].Image;int count=Marks.Count;OpenBackgroundControls();check(backgroundEnabled.Checked==false&&Marks.Count==count&&Background.Size==new Size(200,160),"Background controls start transparent and opening them does not alter the image");
        backgroundFields["Margin"].Number.Value=20;backgroundFields["Padding"].Number.Value=10;FinishBackgroundAdjustment();image=Marks.First(mark=>mark.Kind=="Image");check(Background.Size==new Size(260,220)&&image.X==30&&image.Y==30,"Margin and padding expand the canvas and offset editable content");using(var rendered=Art.Render(Background,Marks))check(rendered.GetPixel(0,0).A==0,"Transparent backgrounds preserve PNG alpha");backgroundFields["Rounded corners"].Number.Value=18;FinishBackgroundAdjustment();using(var rendered=Art.Render(Background,new List<Mark>{image}))check(rendered.GetPixel((int)image.X,(int)image.Y).A==0&&rendered.GetPixel(100,100).A==255,"Rounded image corners preserve source pixels and transparent outer corners");check(Object.ReferenceEquals(original,image.Image),"Background styling retains the original image bytes");
        backgroundRatios["1:1"].PerformClick();FinishBackgroundAdjustment();check(Background.Width==Background.Height,"Canvas ratio buttons produce a square without stretching the image");backgroundEnabled.Checked=true;backgroundFields["Shadow radius"].Number.Value=8;FinishBackgroundAdjustment();check(backgroundFrame.Visible&&Marks.Any(mark=>mark.IsPresentationCard&&mark.Shadow)&&image.W==200&&image.H==160,"Colored backgrounds and cached shadows preserve image dimensions");
        using(var frame=new Bitmap(inspector.Parent.Width,inspector.Parent.Height)){inspector.Parent.DrawToBitmap(frame,new Rectangle(Point.Empty,frame.Size));frame.Save(Path.Combine(folder,"background-controls.png"));}using(var rendered=Art.Render(Background,Marks))rendered.Save(Path.Combine(folder,"background-styled.png"));var savedLayout=Snapshot();check(savedLayout.Marks.First(mark=>mark.IsPresentation).FrameLayout.Ratio=="1:1","Background layout controls persist in project snapshots");
