        using(var menu=new ModernContextMenu {Font=Font}){menu.Items.Add("Undo");menu.Items.Add("Copy image");menu.Items.Add(new ToolStripSeparator());menu.Items.Add("Delete selected layers");menu.Show(this,new Point(40,50));Application.DoEvents();check(menu.Renderer is ModernMenuRenderer&&menu.Region!=null&&menu.Items[0].Height>=28,"Context menus use rounded styling, icons, spacing and shortcut labels");using(var frame=new Bitmap(menu.Width,menu.Height)){menu.DrawToBitmap(frame,new Rectangle(Point.Empty,frame.Size));frame.Save(Path.Combine(folder,"modern-context-menu.png"));}menu.Close();}
