    void VerifyZoneResponsiveness(List<string> report,string folder){
        Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception(label);report.Add("PASS "+label);};
        CloseImageEffects();using(var source=Blank(200,160)){using(var graphics=Graphics.FromImage(source))graphics.Clear(Color.FromArgb(80,80,80));LoadImageDocument(new Bitmap(source),"Zone rotation regression");}OpenImageAdjustmentCard(true);var image=imageAdjustmentTarget;
        var zone=new ImageAdjustmentZone {X=.25f,Y=.375f,W=.5f,H=.25f,Feather=0,Settings=new Mark {Exposure=1}};image.ImageZones.Add(zone);selectedImageZone=zone;zoneAdding=false;SyncImageAdjustmentFields();RefreshImage();
        zone.Angle=90;imageAdjustmentDirty=true;FlushImageAdjustmentPreview();using(var expected=Art.Render(Background,Marks))check(expected.GetPixel(100,45).R>150&&expected.GetPixel(140,80).R==80,"Rotated zones apply their adjustment to the rotated ellipse");
        zone.Angle=37;zone.X=-.15f;zone.Y=-.1f;imageAdjustmentDirty=true;FlushImageAdjustmentPreview();var fast=Art.Bytes(Preview);Art.ClearImageToneCache();using(var expected=Art.Render(Background,Marks))check(fast.SequenceEqual(Art.Bytes(expected)),"Incremental rotated off-edge previews match a fresh full-quality render exactly");check(Background.Size==new Size(200,160),"Off-edge zone adjustments never expand the canvas");
        zone.X=-.5f;zone.Y=.25f;zone.W=.5f;zone.H=.5f;zone.Angle=0;RefreshImage();View.Zoom=1;View.PanX=View.PanY=0;var origin=View.Origin;var canvasSize=Background.Size;var down=new MouseEventArgs(MouseButtons.Left,1,(int)origin.X-50,(int)origin.Y+80,0);check(HandleZoneDown(down)&&zoneHandle==8,"An existing zone can be grabbed beyond the image edge");HandleZoneMove(new MouseEventArgs(MouseButtons.Left,0,down.X-25,down.Y,0));check(zone.X<-.5f&&Background.Size==canvasSize,"Dragging an off-edge zone stays unbounded without resizing the document");CancelZoneGeometry();
        zone.X=.25f;zone.Y=.375f;zone.W=.5f;zone.H=.25f;zone.Angle=0;var rotation=new MouseEventArgs(MouseButtons.Left,1,(int)origin.X+100,(int)origin.Y+34,0);check(HandleZoneDown(rotation)&&zoneHandle==9,"The upper zone handle starts rotation rather than creating a new zone");HandleZoneMove(new MouseEventArgs(MouseButtons.Left,0,(int)origin.X+146,(int)origin.Y+80,0));check(Math.Abs(zone.Angle-90)<1,"Dragging the rotation handle rotates the zone naturally");CancelZoneGeometry();check(zone.Angle==0,"Cancel restores the original zone angle");zone.Angle=27;var snapshot=Snapshot();using(var stream=new MemoryStream()){var serializer=new System.Xml.Serialization.XmlSerializer(typeof(Project));serializer.Serialize(stream,snapshot);stream.Position=0;var restored=(Project)serializer.Deserialize(stream);check(restored.Marks[0].ImageZones[0].Angle==27&&image.Clone().ImageZones[0].Angle==27,"Zone rotation persists in saved projects and duplicate images");}
        image.ImageZones.Add(new ImageAdjustmentZone {X=.1f,Y=.1f,W=.6f,H=.7f,Settings=new Mark {Brightness=15,Saturation=-25}});image.FrameRoundedImage=true;image.Radius=18;image.Exposure=.3f;RefreshImage();zone.X=-.25f;zone.Y=-.1f;zone.Angle=43;imageAdjustmentDirty=true;FlushImageAdjustmentPreview();fast=Art.Bytes(Preview);Art.ClearImageToneCache();using(var expected=Art.Render(Background,Marks))check(fast.SequenceEqual(Art.Bytes(expected)),"Overlapping rotated zones with general adjustments and rounded corners retain exact compositing");
        CloseImageEffects();OpenBackgroundControls();backgroundFields["Margin"].Number.Value=45;backgroundFields["Padding"].Number.Value=15;backgroundFields["Rounded corners"].Number.Value=22;backgroundSmart.Checked=false;backgroundStart=Color.Red;backgroundEnd=Color.Blue;backgroundEnabled.Checked=true;backgroundGradient.Checked=true;FinishBackgroundAdjustment();image=Marks.First(mark=>mark.Kind=="Image");using(var rendered=Art.Render(Background,Marks)){check(rendered.GetPixel(0,0).A==255&&rendered.GetPixel(rendered.Width-1,rendered.Height-1).A==255,"Solid and gradient backgrounds cover the full outer margin including corners");check(rendered.GetPixel((int)image.X-5,(int)image.Y+80).ToArgb()==Color.FromArgb(40,44,55).ToArgb(),"Padding keeps its neutral frame instead of receiving the background gradient");rendered.Save(Path.Combine(folder,"background-margin-fixed.png"));}CloseImageEffects();OpenBackgroundControls();check(backgroundFields["Rounded corners"].Value==22,"Reopening Background retains image rounding independently of outer canvas corners");backgroundEnabled.Checked=false;FinishBackgroundAdjustment();using(var rendered=Art.Render(Background,Marks))check(rendered.GetPixel(0,0).A==0&&rendered.GetPixel((int)image.X-5,(int)image.Y+80).A==255,"Disabling background restores transparent margins while retaining padding");check(Marks.Count(mark=>mark.IsPresentationCard)==1,"Repeated background edits reuse a single padding frame");
        CloseImageEffects();using(var source=Blank(3840,2160)){using(var graphics=Graphics.FromImage(source))graphics.Clear(Color.FromArgb(90,90,90));LoadImageDocument(new Bitmap(source),"4K zones");}OpenImageAdjustmentCard(true);image=imageAdjustmentTarget;zone=new ImageAdjustmentZone {X=.2f,Y=.2f,W=.25f,H=.3f,Settings=new Mark {Exposure=.7f}};image.ImageZones.Add(zone);selectedImageZone=zone;zoneAdding=false;SyncImageAdjustmentFields();RefreshImage();var buffer=Preview;zonePreviewBounds=Art.ZoneDocumentBounds(image,zone);var clock=System.Diagnostics.Stopwatch.StartNew();for(int i=0;i<12;i++){zone.X+=.003f;zone.Angle+=3;imageAdjustmentDirty=true;FlushImageAdjustmentPreview();}clock.Stop();check(Object.ReferenceEquals(buffer,Preview),"Zone drags reuse the full-resolution preview buffer");double ms=clock.Elapsed.TotalMilliseconds/12;report.Add("4K zone benchmark: "+ms.ToString("F2")+" ms/update, 960×648 zone, rotation and full-quality pixels; excludes display latency.");File.WriteAllText(Path.Combine(folder,"zone-performance.txt"),report.Last());fast=Art.Bytes(Preview);Art.ClearImageToneCache();using(var expected=Art.Render(Background,Marks))check(fast.SequenceEqual(Art.Bytes(expected)),"Rapid zone moves leave no stale pixels and match the final export exactly");
